// Die key/value-Zeilen zu einem flachen Objekt falten.
//
// Leere Werte bleiben leer und werden NICHT bemängelt: mail_duo und
// mail_stb sind auf Instanzen, die diese Wege nicht nutzen, zu Recht
// leer. Ob ein bestimmter Wert vorhanden sein MUSS, weiß nur der
// aufrufende Workflow; er prüft es in seinem Konfigurations-Node.

const zeilen = $input.all();
if (zeilen.length === 0) {
  throw new Error('Die Data Table "pw_config" ist leer oder fehlt. Setup erneut laufen lassen (setup.sh --project … n8n) oder die Tabelle in der n8n-Oberfläche unter "Data Tables" anlegen.');
}

const werte = {};
for (const item of zeilen) {
  const key = item.json.key;
  if (key) werte[key] = item.json.value ?? '';
}

return [{ json: werte }];
